import React, { useState, useCallback, useEffect } from 'react';
import { checkVietnameseSpelling, getContractDetails, evaluateContractLegality, compareDocuments, performOcr } from './services/geminiService.ts';
import { CONTRACT_TYPES } from './constants.ts';
import type { SpellCheckResult, ContractDetails, LegalEvaluationResult, ComparisonResult } from './types.ts';
import FileUpload from './components/FileUpload.tsx';
import ResultsDisplay from './components/ResultsDisplay.tsx';
import Loader from './components/Loader.tsx';
import ContractTypeSelector from './components/ContractTypeSelector.tsx';
import ContractDetailsModal from './components/ContractDetailsModal.tsx';
import LegalEvaluationDisplay from './components/LegalEvaluationDisplay.tsx';
import FileDropzone from './components/FileDropzone.tsx';
import ComparisonDisplay from './components/ComparisonDisplay.tsx';

// Khai báo kiểu cho window.aistudio
declare global {
  /* Fix: Explicitly define AIStudio interface to ensure compatibility with environmental types */
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    /* Fix: Remove 'readonly' modifier to match ambient declaration requirements and prevent "identical modifiers" error */
    aistudio: AIStudio;
  }
}

type ActiveTab = 'analyze' | 'compare' | 'ocr';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<ActiveTab>('analyze');
  const [hasApiKey, setHasApiKey] = useState<boolean>(true); // Giả định là có cho đến khi kiểm tra

  // Kiểm tra API Key khi khởi chạy
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleOpenSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true); // Giả định thành công sau khi mở hộp thoại
    }
  };

  // === TABS STYLES ===
  const getTabStyle = (tabName: ActiveTab) => {
    return activeTab === tabName
      ? 'bg-sky-600 text-white shadow-md'
      : 'bg-slate-700/50 text-slate-300 hover:bg-slate-600/50';
  };

  // === SINGLE FILE ANALYSIS STATE ===
  const [file, setFile] = useState<File | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isEvaluating, setIsEvaluating] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedContractId, setSelectedContractId] = useState<string>(CONTRACT_TYPES[0].id);
  const [spellCheckResult, setSpellCheckResult] = useState<SpellCheckResult | null>(null);
  const [legalResult, setLegalResult] = useState<LegalEvaluationResult | null>(null);
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [modalContent, setModalContent] = useState<ContractDetails | null>(null);
  const [isModalLoading, setIsModalLoading] = useState<boolean>(false);
  const [modalError, setModalError] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState<string>('');

  // === DOCUMENT COMPARISON STATE ===
  const [file1, setFile1] = useState<File | null>(null);
  const [file2, setFile2] = useState<File | null>(null);
  const [isComparing, setIsComparing] = useState<boolean>(false);
  const [comparisonResult, setComparisonResult] = useState<ComparisonResult | null>(null);
  const [comparisonError, setComparisonError] = useState<string | null>(null);

  // === OCR STATE ===
  const [ocrFile, setOcrFile] = useState<File | null>(null);
  const [isOcrLoading, setIsOcrLoading] = useState<boolean>(false);
  const [ocrResult, setOcrResult] = useState<string | null>(null);
  const [ocrError, setOcrError] = useState<string | null>(null);

  const handleError = (err: any, setter: (msg: string) => void) => {
    const msg = err instanceof Error ? err.message : String(err);
    if (msg.includes("Requested entity was not found") || msg.includes("API Key")) {
      setHasApiKey(false);
      setter("Lỗi: API Key không hợp lệ hoặc chưa được cấu hình. Vui lòng chọn lại Key trả phí.");
    } else {
      setter(`Lỗi: ${msg}`);
    }
  };

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
    setSpellCheckResult(null);
    setLegalResult(null);
    setError(null);
  };

  const handleCheckSpelling = useCallback(async () => {
    if (!file) {
      setError('Vui lòng chọn một tệp.');
      return;
    }
    setIsLoading(true);
    setLoadingMessage('Đang tải tệp lên và phân tích...');
    setError(null);
    setSpellCheckResult(null);

    try {
      const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
      const contractName = selectedContract ? selectedContract.name : CONTRACT_TYPES[0].name;
      const result = await checkVietnameseSpelling(file, contractName);
      setSpellCheckResult(result);
    } catch (err) {
      handleError(err, setError);
    } finally {
      setIsLoading(false);
      setLoadingMessage('');
    }
  }, [file, selectedContractId]);

  const handleEvaluateLegality = useCallback(async () => {
    if (!file) {
      setError('Vui lòng chọn một tệp.');
      return;
    }
    setIsEvaluating(true);
    setLoadingMessage('Đang tải tệp lên và phân tích rủi ro...');
    setError(null);
    setLegalResult(null);

    try {
        const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
        const contractName = selectedContract ? selectedContract.name : CONTRACT_TYPES[0].name;
        const result = await evaluateContractLegality(file, contractName);
        setLegalResult(result);
    } catch (err) {
        handleError(err, setError);
    } finally {
        setIsEvaluating(false);
        setLoadingMessage('');
    }
  }, [file, selectedContractId]);

  const handleViewDetails = useCallback(async () => {
    const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
    if (!selectedContract || selectedContract.id === 'general') return;

    setIsModalOpen(true);
    setIsModalLoading(true);
    setModalError(null);
    setModalContent(null);

    try {
      const details = await getContractDetails(selectedContract.name);
      setModalContent(details);
    } catch (err) {
      handleError(err, setModalError);
    } finally {
      setIsModalLoading(false);
    }
  }, [selectedContractId]);

  const closeModal = () => {
    setIsModalOpen(false);
  };

  const handleCompare = useCallback(async () => {
      if (!file1 || !file2) {
        setComparisonError("Vui lòng tải lên cả hai tệp để so sánh.");
        return;
      }
      setComparisonError(null);
      setComparisonResult(null);
      setIsComparing(true);
      setLoadingMessage("Đang so sánh hai văn bản...");

      try {
        const result = await compareDocuments(file1, file2);
        setComparisonResult(result);
      } catch (err) {
        handleError(err, setComparisonError);
      } finally {
        setIsComparing(false);
        setLoadingMessage('');
      }
  }, [file1, file2]);

  const handlePerformOcr = useCallback(async () => {
      if (!ocrFile) {
          setOcrError("Vui lòng chọn một tệp ảnh hoặc PDF.");
          return;
      }
      setOcrError(null);
      setOcrResult(null);
      setIsOcrLoading(true);
      setLoadingMessage('Đang thực hiện nhận dạng ký tự...');

      try {
          const result = await performOcr(ocrFile);
          setOcrResult(result.text);
      } catch (err) {
          handleError(err, setOcrError);
      } finally {
          setIsOcrLoading(false);
          setLoadingMessage('');
      }
  }, [ocrFile]);

  if (!hasApiKey && window.aistudio) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 p-4">
        <div className="max-w-md w-full bg-slate-800 p-8 rounded-2xl border border-slate-700 shadow-2xl text-center">
          <div className="w-16 h-16 bg-amber-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m0 0v2m0-2h2m-2 0H8m13 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          </div>
          <h2 className="text-2xl font-bold text-white mb-4">Yêu cầu API Key</h2>
          <p className="text-slate-400 mb-6">
            Ứng dụng yêu cầu API Key trả phí từ Google Cloud để sử dụng các mô hình AI cao cấp. Vui lòng chọn Key của bạn để tiếp tục.
          </p>
          <button
            onClick={handleOpenSelectKey}
            className="w-full py-3 bg-sky-600 hover:bg-sky-700 text-white font-bold rounded-lg transition-colors mb-4"
          >
            Chọn API Key
          </button>
          <a 
            href="https://ai.google.dev/gemini-api/docs/billing" 
            target="_blank" 
            rel="noopener noreferrer"
            className="text-sky-400 hover:underline text-sm"
          >
            Tìm hiểu về thanh toán & API Key
          </a>
        </div>
      </div>
    );
  }

  const selectedContractName = CONTRACT_TYPES.find(c => c.id === selectedContractId)?.name || 'Chi tiết Hợp đồng';

  return (
    <>
      <div className="min-h-screen flex flex-col items-center justify-center p-4 sm:p-6 lg:p-8 font-sans">
        <div className="w-full max-w-4xl mx-auto">
          <header className="text-center mb-8">
            <h1 className="text-4xl sm:text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-sky-400 to-blue-500">
              Trợ lý Pháp lý AI
            </h1>
            <p className="mt-3 text-lg text-slate-400">
              Phân tích, đánh giá, so sánh hợp đồng và các tài liệu pháp lý.
            </p>
          </header>

          <main className="bg-slate-800/50 backdrop-blur-sm rounded-2xl shadow-2xl shadow-slate-950/50 border border-slate-700">
             <div className="flex p-2 bg-slate-900/40 rounded-t-2xl border-b border-slate-700 overflow-x-auto">
                <button onClick={() => setActiveTab('analyze')} className={`flex-1 py-2 px-4 rounded-lg font-semibold transition-all duration-200 whitespace-nowrap min-w-[120px] ${getTabStyle('analyze')}`}>
                  Phân tích File
                </button>
                <button onClick={() => setActiveTab('compare')} className={`flex-1 py-2 px-4 rounded-lg font-semibold transition-all duration-200 whitespace-nowrap min-w-[120px] ${getTabStyle('compare')}`}>
                  So sánh 2 File
                </button>
                <button onClick={() => setActiveTab('ocr')} className={`flex-1 py-2 px-4 rounded-lg font-semibold transition-all duration-200 whitespace-nowrap min-w-[120px] ${getTabStyle('ocr')}`}>
                  OCR (Ảnh/PDF)
                </button>
             </div>

            {activeTab === 'analyze' && (
              <div className="p-6 sm:p-8">
                <ContractTypeSelector
                  selectedType={selectedContractId}
                  onTypeChange={setSelectedContractId}
                  contractTypes={CONTRACT_TYPES}
                  onViewDetails={handleViewDetails}
                />
                <FileUpload
                  file={file}
                  onFileSelect={handleFileSelect}
                  onCheck={handleCheckSpelling}
                  onEvaluate={handleEvaluateLegality}
                  isLoading={isLoading}
                  isEvaluating={isEvaluating}
                />
                {error && (
                  <div className="mt-6 p-4 bg-red-900/50 text-red-300 border border-red-700 rounded-lg text-center">
                    {error}
                  </div>
                )}
                {(isLoading || isEvaluating) && <Loader message={loadingMessage}/>}
                {spellCheckResult && !isLoading && (
                  <div className="mt-8">
                    <h2 className="text-2xl font-semibold mb-4 text-slate-100 border-b border-slate-700 pb-2">Kết quả phân tích Chính tả & Thể thức</h2>
                    <ResultsDisplay result={spellCheckResult} />
                  </div>
                )}
                {legalResult && !isEvaluating && (
                  <div className="mt-8">
                    <h2 className="text-2xl font-semibold mb-4 text-slate-100 border-b border-slate-700 pb-2">Kết quả Phân tích Lỗ hổng Pháp lý</h2>
                    <LegalEvaluationDisplay result={legalResult} />
                  </div>
                )}
              </div>
            )}

            {activeTab === 'compare' && (
               <div className="p-6 sm:p-8">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                    <FileDropzone file={file1} onFileSelect={setFile1} title="Tài liệu 1" acceptedFormats="documents" />
                    <FileDropzone file={file2} onFileSelect={setFile2} title="Tài liệu 2" acceptedFormats="documents" />
                  </div>
                   <div className="flex justify-center">
                      <button
                        onClick={handleCompare}
                        disabled={!file1 || !file2 || isComparing}
                        className="w-full sm:w-auto px-10 py-3 text-base font-semibold text-white bg-green-600 rounded-lg shadow-md hover:bg-green-700 disabled:bg-slate-600 disabled:cursor-not-allowed transition-colors duration-300"
                      >
                        {isComparing ? 'Đang xử lý...' : 'Bắt đầu so sánh'}
                      </button>
                   </div>
                   {comparisonError && (
                      <div className="mt-6 p-4 bg-red-900/50 text-red-300 border border-red-700 rounded-lg text-center">
                          {comparisonError}
                      </div>
                   )}
                   {isComparing && <Loader message={loadingMessage}/>}
                   {comparisonResult && !isComparing && (
                      <div className="mt-8">
                        <h2 className="text-2xl font-semibold mb-4 text-slate-100 border-b border-slate-700 pb-2">Kết quả So sánh</h2>
                        <ComparisonDisplay result={comparisonResult}/>
                      </div>
                   )}
               </div>
            )}

            {activeTab === 'ocr' && (
              <div className="p-6 sm:p-8">
                <h2 className="text-2xl font-semibold mb-4 text-center text-slate-100">OCR - Trích xuất văn bản</h2>
                <p className="text-center text-slate-400 mb-6 max-w-2xl mx-auto">
                  Số hóa tài liệu giấy từ ảnh (PNG, JPG) hoặc PDF quét.
                </p>
                <div className="max-w-xl mx-auto">
                    <FileDropzone file={ocrFile} onFileSelect={setOcrFile} title="Tải ảnh hoặc PDF lên" acceptedFormats="ocr" />
                </div>
                <div className="flex justify-center mt-6">
                    <button
                        onClick={handlePerformOcr}
                        disabled={!ocrFile || isOcrLoading}
                        className="w-full sm:w-auto px-10 py-3 text-base font-semibold text-white bg-teal-600 rounded-lg shadow-md hover:bg-teal-700 disabled:bg-slate-600 disabled:cursor-not-allowed transition-colors duration-300"
                    >
                        {isOcrLoading ? 'Đang xử lý...' : 'Trích xuất văn bản'}
                    </button>
                </div>
                {ocrError && (
                    <div className="mt-6 p-4 bg-red-900/50 text-red-300 border border-red-700 rounded-lg text-center">
                        {ocrError}
                    </div>
                )}
                {isOcrLoading && <Loader message={loadingMessage} />}
                {ocrResult && !isOcrLoading && (
                    <div className="mt-8">
                        <h3 className="text-xl font-semibold mb-4 text-slate-100">Văn bản nhận diện:</h3>
                        <div className="relative">
                            <textarea
                                readOnly
                                value={ocrResult}
                                className="w-full h-64 p-4 bg-slate-900 border border-slate-700 rounded-lg text-slate-300 font-mono"
                            />
                            <button
                                onClick={() => navigator.clipboard.writeText(ocrResult)}
                                className="absolute top-3 right-3 px-3 py-1 text-xs font-semibold text-sky-200 bg-sky-800/70 rounded-md hover:bg-sky-700"
                            >
                                Sao chép
                            </button>
                        </div>
                    </div>
                )}
              </div>
            )}
          </main>

          <footer className="text-center mt-8 text-slate-500 text-sm">
            <p>
              Cung cấp bởi AI <span className="text-red-700 font-bold">(DI-IT)</span>. Dữ liệu huấn luyện từ Cổng thông tin Pháp luật Quốc gia.
            </p>
          </footer>
        </div>
      </div>
      <ContractDetailsModal
        isOpen={isModalOpen}
        onClose={closeModal}
        title={selectedContractName}
        content={modalContent}
        isLoading={isModalLoading}
        error={modalError}
      />
    </>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import type { SpellCheckResult, ContractDetails, LegalEvaluationResult, ComparisonResult, OcrResult } from '../types';
import { readFileContent } from '../utils/fileReader';

/**
 * Khởi tạo AI Client.
 * API Key được lấy trực tiếp từ process.env.API_KEY theo quy định của SDK.
 */
const createAiClient = () => {
  const apiKey = process.env.API_KEY;
  // Trong môi trường trình duyệt của AI Studio, process.env.API_KEY sẽ được chèn tự động khi build.
  return new GoogleGenAI({ apiKey: apiKey as string });
};

const safeJsonParse = (text: string | undefined) => {
  if (!text) throw new Error("AI không phản hồi dữ liệu.");
  let clean = text.trim();
  const match = clean.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  if (match) clean = match[1].trim();

  try {
    return JSON.parse(clean);
  } catch (e) {
    console.error("Lỗi Parse JSON:", clean);
    throw new Error("Dữ liệu phản hồi từ AI không đúng định dạng JSON.");
  }
};

export const checkVietnameseSpelling = async (file: File, contractName: string): Promise<SpellCheckResult> => {
  const text = await readFileContent(file);
  const ai = createAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Bạn là trợ lý pháp lý Việt Nam. Kiểm tra chính tả và thể thức văn bản cho: ${contractName}.\n\nNội dung:\n${text}`,
    config: { 
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          hasErrors: { type: Type.BOOLEAN },
          errors: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                incorrectWord: { type: Type.STRING },
                correctedWord: { type: Type.STRING },
                context: { type: Type.STRING }
              }
            }
          },
          formatErrors: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                errorType: { type: Type.STRING },
                description: { type: Type.STRING },
                recommendation: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  });
  return safeJsonParse(response.text);
};

export const evaluateContractLegality = async (file: File, contractName: string): Promise<LegalEvaluationResult> => {
  const text = await readFileContent(file);
  const ai = createAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Bạn là luật sư chuyên gia. Phân tích rủi ro pháp lý và lỗ hổng hợp đồng cho: ${contractName}. Đưa ra khuyến nghị chi tiết.\n\nNội dung:\n${text}`,
    config: { 
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          legalScore: { type: Type.NUMBER },
          feedback: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                type: { type: Type.STRING },
                clause: { type: Type.STRING },
                comment: { type: Type.STRING },
                recommendation: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  });
  return safeJsonParse(response.text);
};

export const getContractDetails = async (contractName: string): Promise<ContractDetails> => {
  const ai = createAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Cung cấp chi tiết các quy định pháp luật hiện hành và các điều khoản mẫu bắt buộc cho: ${contractName}`
  });
  return { details: response.text || "Không có dữ liệu chi tiết." };
};

export const compareDocuments = async (file1: File, file2: File): Promise<ComparisonResult> => {
  const text1 = await readFileContent(file1);
  const text2 = await readFileContent(file2);
  const ai = createAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `So sánh hai văn bản sau để tìm điểm tương đồng và khác biệt chính:\n\nVăn bản 1: ${text1}\n\nVăn bản 2: ${text2}`,
    config: { 
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          similarityScore: { type: Type.NUMBER },
          matches: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                textFromFile1: { type: Type.STRING },
                textFromFile2: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  });
  return safeJsonParse(response.text);
};

export const performOcr = async (file: File): Promise<OcrResult> => {
  const text = await readFileContent(file);
  return { text };
};

import React, { useState, useCallback, useEffect } from 'react';
import { checkVietnameseSpelling, getContractDetails, evaluateContractLegality, compareDocuments, performOcr } from './services/geminiService.ts';
import { CONTRACT_TYPES } from './constants.ts';
import type { SpellCheckResult, ContractDetails, LegalEvaluationResult, ComparisonResult } from './types.ts';
import FileUpload from './components/FileUpload.tsx';
import ResultsDisplay from './components/ResultsDisplay.tsx';
import Loader from './components/Loader.tsx';
import ContractTypeSelector from './components/ContractTypeSelector.tsx';
import ContractDetailsModal from './components/ContractDetailsModal.tsx';
import LegalEvaluationDisplay from './components/LegalEvaluationDisplay.tsx';
import FileDropzone from './components/FileDropzone.tsx';
import ComparisonDisplay from './components/ComparisonDisplay.tsx';

// Khai báo kiểu cho window.aistudio
declare global {
  /* Fix: Explicitly define AIStudio interface to ensure compatibility with environmental types */
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    /* Fix: Restore 'readonly' modifier to match ambient declaration requirements and resolve "identical modifiers" error */
    readonly aistudio: AIStudio;
  }
}

type ActiveTab = 'analyze' | 'compare' | 'ocr';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<ActiveTab>('analyze');
  const [hasApiKey, setHasApiKey] = useState<boolean>(true); // Giả định là có cho đến khi kiểm tra

  // Kiểm tra API Key khi khởi chạy
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleOpenSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true); // Giả định thành công sau khi mở hộp thoại
    }
  };

  // === TABS STYLES ===
  const getTabStyle = (tabName: ActiveTab) => {
    return activeTab === tabName
      ? 'bg-sky-600 text-white shadow-md'
      : 'bg-slate-700/50 text-slate-300 hover:bg-slate-600/50';
  };

  // === SINGLE FILE ANALYSIS STATE ===
  const [file, setFile] = useState<File | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isEvaluating, setIsEvaluating] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedContractId, setSelectedContractId] = useState<string>(CONTRACT_TYPES[0].id);
  const [spellCheckResult, setSpellCheckResult] = useState<SpellCheckResult | null>(null);
  const [legalResult, setLegalResult] = useState<LegalEvaluationResult | null>(null);
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [modalContent, setModalContent] = useState<ContractDetails | null>(null);
  const [isModalLoading, setIsModalLoading] = useState<boolean>(false);
  const [modalError, setModalError] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState<string>('');

  // === DOCUMENT COMPARISON STATE ===
  const [file1, setFile1] = useState<File | null>(null);
  const [file2, setFile2] = useState<File | null>(null);
  const [isComparing, setIsComparing] = useState<boolean>(false);
  const [comparisonResult, setComparisonResult] = useState<ComparisonResult | null>(null);
  const [comparisonError, setComparisonError] = useState<string | null>(null);

  // === OCR STATE ===
  const [ocrFile, setOcrFile] = useState<File | null>(null);
  const [isOcrLoading, setIsOcrLoading] = useState<boolean>(false);
  const [ocrResult, setOcrResult] = useState<string | null>(null);
  const [ocrError, setOcrError] = useState<string | null>(null);

  const handleError = (err: any, setter: (msg: string) => void) => {
    const msg = err instanceof Error ? err.message : String(err);
    if (msg.includes("Requested entity was not found") || msg.includes("API Key")) {
      setHasApiKey(false);
      setter("Lỗi: API Key không hợp lệ hoặc chưa được cấu hình. Vui lòng chọn lại Key trả phí.");
    } else {
      setter(`Lỗi: ${msg}`);
    }
  };

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
    setSpellCheckResult(null);
    setLegalResult(null);
    setError(null);
  };

  const handleCheckSpelling = useCallback(async () => {
    if (!file) {
      setError('Vui lòng chọn một tệp.');
      return;
    }
    setIsLoading(true);
    setLoadingMessage('Đang tải tệp lên và phân tích...');
    setError(null);
    setSpellCheckResult(null);

    try {
      const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
      const contractName = selectedContract ? selectedContract.name : CONTRACT_TYPES[0].name;
      const result = await checkVietnameseSpelling(file, contractName);
      setSpellCheckResult(result);
    } catch (err) {
      handleError(err, setError);
    } finally {
      setIsLoading(false);
      setLoadingMessage('');
    }
  }, [file, selectedContractId]);

  const handleEvaluateLegality = useCallback(async () => {
    if (!file) {
      setError('Vui lòng chọn một tệp.');
      return;
    }
    setIsEvaluating(true);
    setLoadingMessage('Đang tải tệp lên và phân tích rủi ro...');
    setError(null);
    setLegalResult(null);

    try {
        const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
        const contractName = selectedContract ? selectedContract.name : CONTRACT_TYPES[0].name;
        const result = await evaluateContractLegality(file, contractName);
        setLegalResult(result);
    } catch (err) {
        handleError(err, setError);
    } finally {
        setIsEvaluating(false);
        setLoadingMessage('');
    }
  }, [file, selectedContractId]);

  const handleViewDetails = useCallback(async () => {
    const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
    if (!selectedContract || selectedContract.id === 'general') return;

    setIsModalOpen(true);
    setIsModalLoading(true);
    setModalError(null);
    setModalContent(null);

    try {
      const details = await getContractDetails(selectedContract.name);
      setModalContent(details);
    } catch (err) {
      handleError(err, setModalError);
    } finally {
      setIsModalLoading(false);
    }
  }, [selectedContractId]);

  const closeModal = () => {
    setIsModalOpen(false);
  };

  const handleCompare = useCallback(async () => {
      if (!file1 || !file2) {
        setComparisonError("Vui lòng tải lên cả hai tệp để so sánh.");
        return;
      }
      setComparisonError(null);
      setComparisonResult(null);
      setIsComparing(true);
      setLoadingMessage("Đang so sánh hai văn bản...");

      try {
        const result = await compareDocuments(file1, file2);
        setComparisonResult(result);
      } catch (err) {
        handleError(err, setComparisonError);
      } finally {
        setIsComparing(false);
        setLoadingMessage('');
      }
  }, [file1, file2]);

  const handlePerformOcr = useCallback(async () => {
      if (!ocrFile) {
          setOcrError("Vui lòng chọn một tệp ảnh hoặc PDF.");
          return;
      }
      setOcrError(null);
      setOcrResult(null);
      setIsOcrLoading(true);
      setLoadingMessage('Đang thực hiện nhận dạng ký tự...');

      try {
          const result = await performOcr(ocrFile);
          setOcrResult(result.text);
      } catch (err) {
          handleError(err, setOcrError);
      } finally {
          setIsOcrLoading(false);
          setLoadingMessage('');
      }
  }, [ocrFile]);

  if (!hasApiKey && window.aistudio) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 p-4">
        <div className="max-w-md w-full bg-slate-800 p-8 rounded-2xl border border-slate-700 shadow-2xl text-center">
          <div className="w-16 h-16 bg-amber-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m0 0v2m0-2h2m-2 0H8m13 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          </div>
          <h2 className="text-2xl font-bold text-white mb-4">Yêu cầu API Key</h2>
          <p className="text-slate-400 mb-6">
            Ứng dụng yêu cầu API Key trả phí từ Google Cloud để sử dụng các mô hình AI cao cấp. Vui lòng chọn Key của bạn để tiếp tục.
          </p>
          <button
            onClick={handleOpenSelectKey}
            className="w-full py-3 bg-sky-600 hover:bg-sky-700 text-white font-bold rounded-lg transition-colors mb-4"
          >
            Chọn API Key
          </button>
          <a 
            href="https://ai.google.dev/gemini-api/docs/billing" 
            target="_blank" 
            rel="noopener noreferrer"
            className="text-sky-400 hover:underline text-sm"
          >
            Tìm hiểu về thanh toán & API Key
          </a>
        </div>
      </div>
    );
  }

  const selectedContractName = CONTRACT_TYPES.find(c => c.id === selectedContractId)?.name || 'Chi tiết Hợp đồng';

  return (
    <>
      <div className="min-h-screen flex flex-col items-center justify-center p-4 sm:p-6 lg:p-8 font-sans">
        <div className="w-full max-w-4xl mx-auto">
          <header className="text-center mb-8">
            <h1 className="text-4xl sm:text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-sky-400 to-blue-500">
              Trợ lý Pháp lý AI
            </h1>
            <p className="mt-3 text-lg text-slate-400">
              Phân tích, đánh giá, so sánh hợp đồng và các tài liệu pháp lý.
            </p>
          </header>

          <main className="bg-slate-800/50 backdrop-blur-sm rounded-2xl shadow-2xl shadow-slate-950/50 border border-slate-700">
             <div className="flex p-2 bg-slate-900/40 rounded-t-2xl border-b border-slate-700 overflow-x-auto">
                <button onClick={() => setActiveTab('analyze')} className={`flex-1 py-2 px-4 rounded-lg font-semibold transition-all duration-200 whitespace-nowrap min-w-[120px] ${getTabStyle('analyze')}`}>
                  Phân tích File
                </button>
                <button onClick={() => setActiveTab('compare')} className={`flex-1 py-2 px-4 rounded-lg font-semibold transition-all duration-200 whitespace-nowrap min-w-[120px] ${getTabStyle('compare')}`}>
                  So sánh 2 File
                </button>
                <button onClick={() => setActiveTab('ocr')} className={`flex-1 py-2 px-4 rounded-lg font-semibold transition-all duration-200 whitespace-nowrap min-w-[120px] ${getTabStyle('ocr')}`}>
                  OCR (Ảnh/PDF)
                </button>
             </div>

            {activeTab === 'analyze' && (
              <div className="p-6 sm:p-8">
                <ContractTypeSelector
                  selectedType={selectedContractId}
                  onTypeChange={setSelectedContractId}
                  contractTypes={CONTRACT_TYPES}
                  onViewDetails={handleViewDetails}
                />
                <FileUpload
                  file={file}
                  onFileSelect={handleFileSelect}
                  onCheck={handleCheckSpelling}
                  onEvaluate={handleEvaluateLegality}
                  isLoading={isLoading}
                  isEvaluating={isEvaluating}
                />
                {error && (
                  <div className="mt-6 p-4 bg-red-900/50 text-red-300 border border-red-700 rounded-lg text-center">
                    {error}
                  </div>
                )}
                {(isLoading || isEvaluating) && <Loader message={loadingMessage}/>}
                {spellCheckResult && !isLoading && (
                  <div className="mt-8">
                    <h2 className="text-2xl font-semibold mb-4 text-slate-100 border-b border-slate-700 pb-2">Kết quả phân tích Chính tả & Thể thức</h2>
                    <ResultsDisplay result={spellCheckResult} />
                  </div>
                )}
                {legalResult && !isEvaluating && (
                  <div className="mt-8">
                    <h2 className="text-2xl font-semibold mb-4 text-slate-100 border-b border-slate-700 pb-2">Kết quả Phân tích Lỗ hổng Pháp lý</h2>
                    <LegalEvaluationDisplay result={legalResult} />
                  </div>
                )}
              </div>
            )}

            {activeTab === 'compare' && (
               <div className="p-6 sm:p-8">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                    <FileDropzone file={file1} onFileSelect={setFile1} title="Tài liệu 1" acceptedFormats="documents" />
                    <FileDropzone file={file2} onFileSelect={setFile2} title="Tài liệu 2" acceptedFormats="documents" />
                  </div>
                   <div className="flex justify-center">
                      <button
                        onClick={handleCompare}
                        disabled={!file1 || !file2 || isComparing}
                        className="w-full sm:w-auto px-10 py-3 text-base font-semibold text-white bg-green-600 rounded-lg shadow-md hover:bg-green-700 disabled:bg-slate-600 disabled:cursor-not-allowed transition-colors duration-300"
                      >
                        {isComparing ? 'Đang xử lý...' : 'Bắt đầu so sánh'}
                      </button>
                   </div>
                   {comparisonError && (
                      <div className="mt-6 p-4 bg-red-900/50 text-red-300 border border-red-700 rounded-lg text-center">
                          {comparisonError}
                      </div>
                   )}
                   {isComparing && <Loader message={loadingMessage}/>}
                   {comparisonResult && !isComparing && (
                      <div className="mt-8">
                        <h2 className="text-2xl font-semibold mb-4 text-slate-100 border-b border-slate-700 pb-2">Kết quả So sánh</h2>
                        <ComparisonDisplay result={comparisonResult}/>
                      </div>
                   )}
               </div>
            )}

            {activeTab === 'ocr' && (
              <div className="p-6 sm:p-8">
                <h2 className="text-2xl font-semibold mb-4 text-center text-slate-100">OCR - Trích xuất văn bản</h2>
                <p className="text-center text-slate-400 mb-6 max-w-2xl mx-auto">
                  Số hóa tài liệu giấy từ ảnh (PNG, JPG) hoặc PDF quét.
                </p>
                <div className="max-w-xl mx-auto">
                    <FileDropzone file={ocrFile} onFileSelect={setOcrFile} title="Tải ảnh hoặc PDF lên" acceptedFormats="ocr" />
                </div>
                <div className="flex justify-center mt-6">
                    <button
                        onClick={handlePerformOcr}
                        disabled={!ocrFile || isOcrLoading}
                        className="w-full sm:w-auto px-10 py-3 text-base font-semibold text-white bg-teal-600 rounded-lg shadow-md hover:bg-teal-700 disabled:bg-slate-600 disabled:cursor-not-allowed transition-colors duration-300"
                    >
                        {isOcrLoading ? 'Đang xử lý...' : 'Trích xuất văn bản'}
                    </button>
                </div>
                {ocrError && (
                    <div className="mt-6 p-4 bg-red-900/50 text-red-300 border border-red-700 rounded-lg text-center">
                        {ocrError}
                    </div>
                )}
                {isOcrLoading && <Loader message={loadingMessage} />}
                {ocrResult && !isOcrLoading && (
                    <div className="mt-8">
                        <h3 className="text-xl font-semibold mb-4 text-slate-100">Văn bản nhận diện:</h3>
                        <div className="relative">
                            <textarea
                                readOnly
                                value={ocrResult}
                                className="w-full h-64 p-4 bg-slate-900 border border-slate-700 rounded-lg text-slate-300 font-mono"
                            />
                            <button
                                onClick={() => navigator.clipboard.writeText(ocrResult)}
                                className="absolute top-3 right-3 px-3 py-1 text-xs font-semibold text-sky-200 bg-sky-800/70 rounded-md hover:bg-sky-700"
                            >
                                Sao chép
                            </button>
                        </div>
                    </div>
                )}
              </div>
            )}
          </main>

          <footer className="text-center mt-8 text-slate-500 text-sm">
            <p>
              Cung cấp bởi AI <span className="text-red-700 font-bold">(DI-IT)</span>. Dữ liệu huấn luyện từ Cổng thông tin Pháp luật Quốc gia.
            </p>
          </footer>
        </div>
      </div>
      <ContractDetailsModal
        isOpen={isModalOpen}
        onClose={closeModal}
        title={selectedContractName}
        content={modalContent}
        isLoading={isModalLoading}
        error={modalError}
      />
    </>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import type { SpellCheckResult, ContractDetails, LegalEvaluationResult, ComparisonResult, OcrResult } from '../types';
import { readFileContent } from '../utils/fileReader';

/**
 * Khởi tạo AI Client.
 * API Key được lấy trực tiếp từ process.env.API_KEY.
 * Lưu ý: KHÔNG gán khóa này vào một biến trung gian trước khi truyền vào constructor 
 * để đảm bảo quá trình chèn biến môi trường của nền tảng hoạt động chính xác.
 */
const createAiClient = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key chưa được thiết lập. Vui lòng sử dụng tính năng 'Chọn API Key' trong ứng dụng.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const safeJsonParse = (text: string | undefined) => {
  if (!text) throw new Error("AI không phản hồi dữ liệu.");
  let clean = text.trim();
  const match = clean.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  if (match) clean = match[1].trim();

  try {
    return JSON.parse(clean);
  } catch (e) {
    console.error("Lỗi Parse JSON:", clean);
    throw new Error("Dữ liệu phản hồi từ AI không đúng định dạng JSON.");
  }
};

export const checkVietnameseSpelling = async (file: File, contractName: string): Promise<SpellCheckResult> => {
  const text = await readFileContent(file);
  const ai = createAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Bạn là trợ lý pháp lý Việt Nam. Kiểm tra chính tả và thể thức văn bản cho: ${contractName}.\n\nNội dung:\n${text}`,
    config: { 
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          hasErrors: { type: Type.BOOLEAN },
          errors: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                incorrectWord: { type: Type.STRING },
                correctedWord: { type: Type.STRING },
                context: { type: Type.STRING }
              }
            }
          },
          formatErrors: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                errorType: { type: Type.STRING },
                description: { type: Type.STRING },
                recommendation: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  });
  return safeJsonParse(response.text);
};

export const evaluateContractLegality = async (file: File, contractName: string): Promise<LegalEvaluationResult> => {
  const text = await readFileContent(file);
  const ai = createAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Bạn là luật sư chuyên gia. Phân tích rủi ro pháp lý và lỗ hổng hợp đồng cho: ${contractName}. Đưa ra khuyến nghị chi tiết.\n\nNội dung:\n${text}`,
    config: { 
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          legalScore: { type: Type.NUMBER },
          feedback: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                type: { type: Type.STRING },
                clause: { type: Type.STRING },
                comment: { type: Type.STRING },
                recommendation: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  });
  return safeJsonParse(response.text);
};

export const getContractDetails = async (contractName: string): Promise<ContractDetails> => {
  const ai = createAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Cung cấp chi tiết các quy định pháp luật hiện hành và các điều khoản mẫu bắt buộc cho: ${contractName}`
  });
  return { details: response.text || "Không có dữ liệu chi tiết." };
};

export const compareDocuments = async (file1: File, file2: File): Promise<ComparisonResult> => {
  const text1 = await readFileContent(file1);
  const text2 = await readFileContent(file2);
  const ai = createAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `So sánh hai văn bản sau để tìm điểm tương đồng và khác biệt chính:\n\nVăn bản 1: ${text1}\n\nVăn bản 2: ${text2}`,
    config: { 
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          similarityScore: { type: Type.NUMBER },
          matches: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                textFromFile1: { type: Type.STRING },
                textFromFile2: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  });
  return safeJsonParse(response.text);
};

export const performOcr = async (file: File): Promise<OcrResult> => {
  const text = await readFileContent(file);
  return { text };
};

import React, { useState, useCallback, useEffect } from 'react';
import { checkVietnameseSpelling, getContractDetails, evaluateContractLegality, compareDocuments, performOcr } from './services/geminiService.ts';
import { CONTRACT_TYPES } from './constants.ts';
import type { SpellCheckResult, ContractDetails, LegalEvaluationResult, ComparisonResult } from './types.ts';
import FileUpload from './components/FileUpload.tsx';
import ResultsDisplay from './components/ResultsDisplay.tsx';
import Loader from './components/Loader.tsx';
import ContractTypeSelector from './components/ContractTypeSelector.tsx';
import ContractDetailsModal from './components/ContractDetailsModal.tsx';
import LegalEvaluationDisplay from './components/LegalEvaluationDisplay.tsx';
import FileDropzone from './components/FileDropzone.tsx';
import ComparisonDisplay from './components/ComparisonDisplay.tsx';

// Khai báo kiểu cho window.aistudio
declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    readonly aistudio: AIStudio;
  }
}

type ActiveTab = 'analyze' | 'compare' | 'ocr';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<ActiveTab>('analyze');
  const [hasApiKey, setHasApiKey] = useState<boolean>(true); 

  // Kiểm tra API Key khi khởi chạy
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleOpenSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // Giả định thành công sau khi kích hoạt hộp thoại chọn khóa
      setHasApiKey(true);
    }
  };

  // === TABS STYLES ===
  const getTabStyle = (tabName: ActiveTab) => {
    return activeTab === tabName
      ? 'bg-sky-600 text-white shadow-md'
      : 'bg-slate-700/50 text-slate-300 hover:bg-slate-600/50';
  };

  // === SINGLE FILE ANALYSIS STATE ===
  const [file, setFile] = useState<File | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isEvaluating, setIsEvaluating] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedContractId, setSelectedContractId] = useState<string>(CONTRACT_TYPES[0].id);
  const [spellCheckResult, setSpellCheckResult] = useState<SpellCheckResult | null>(null);
  const [legalResult, setLegalResult] = useState<LegalEvaluationResult | null>(null);
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [modalContent, setModalContent] = useState<ContractDetails | null>(null);
  const [isModalLoading, setIsModalLoading] = useState<boolean>(false);
  const [modalError, setModalError] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState<string>('');

  // === DOCUMENT COMPARISON STATE ===
  const [file1, setFile1] = useState<File | null>(null);
  const [file2, setFile2] = useState<File | null>(null);
  const [isComparing, setIsComparing] = useState<boolean>(false);
  const [comparisonResult, setComparisonResult] = useState<ComparisonResult | null>(null);
  const [comparisonError, setComparisonError] = useState<string | null>(null);

  // === OCR STATE ===
  const [ocrFile, setOcrFile] = useState<File | null>(null);
  const [isOcrLoading, setIsOcrLoading] = useState<boolean>(false);
  const [ocrResult, setOcrResult] = useState<string | null>(null);
  const [ocrError, setOcrError] = useState<string | null>(null);

  const handleError = (err: any, setter: (msg: string) => void) => {
    const msg = err instanceof Error ? err.message : String(err);
    if (msg.includes("Requested entity was not found") || msg.includes("API Key") || msg.includes("not be set")) {
      setHasApiKey(false);
      setter("Lỗi: API Key không hợp lệ hoặc chưa được cấu hình. Vui lòng bấm 'Chọn API Key' bên dưới.");
    } else {
      setter(`Lỗi: ${msg}`);
    }
  };

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
    setSpellCheckResult(null);
    setLegalResult(null);
    setError(null);
  };

  const handleCheckSpelling = useCallback(async () => {
    if (!file) {
      setError('Vui lòng chọn một tệp.');
      return;
    }
    setIsLoading(true);
    setLoadingMessage('Đang tải tệp lên và phân tích...');
    setError(null);
    setSpellCheckResult(null);

    try {
      const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
      const contractName = selectedContract ? selectedContract.name : CONTRACT_TYPES[0].name;
      const result = await checkVietnameseSpelling(file, contractName);
      setSpellCheckResult(result);
    } catch (err) {
      handleError(err, setError);
    } finally {
      setIsLoading(false);
      setLoadingMessage('');
    }
  }, [file, selectedContractId]);

  const handleEvaluateLegality = useCallback(async () => {
    if (!file) {
      setError('Vui lòng chọn một tệp.');
      return;
    }
    setIsEvaluating(true);
    setLoadingMessage('Đang tải tệp lên và phân tích rủi ro...');
    setError(null);
    setLegalResult(null);

    try {
        const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
        const contractName = selectedContract ? selectedContract.name : CONTRACT_TYPES[0].name;
        const result = await evaluateContractLegality(file, contractName);
        setLegalResult(result);
    } catch (err) {
        handleError(err, setError);
    } finally {
        setIsEvaluating(false);
        setLoadingMessage('');
    }
  }, [file, selectedContractId]);

  const handleViewDetails = useCallback(async () => {
    const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
    if (!selectedContract || selectedContract.id === 'general') return;

    setIsModalOpen(true);
    setIsModalLoading(true);
    setModalError(null);
    setModalContent(null);

    try {
      const details = await getContractDetails(selectedContract.name);
      setModalContent(details);
    } catch (err) {
      handleError(err, setModalError);
    } finally {
      setIsModalLoading(false);
    }
  }, [selectedContractId]);

  const closeModal = () => {
    setIsModalOpen(false);
  };

  const handleCompare = useCallback(async () => {
      if (!file1 || !file2) {
        setComparisonError("Vui lòng tải lên cả hai tệp để so sánh.");
        return;
      }
      setComparisonError(null);
      setComparisonResult(null);
      setIsComparing(true);
      setLoadingMessage("Đang so sánh hai văn bản...");

      try {
        const result = await compareDocuments(file1, file2);
        setComparisonResult(result);
      } catch (err) {
        handleError(err, setComparisonError);
      } finally {
        setIsComparing(false);
        setLoadingMessage('');
      }
  }, [file1, file2]);

  const handlePerformOcr = useCallback(async () => {
      if (!ocrFile) {
          setOcrError("Vui lòng chọn một tệp ảnh hoặc PDF.");
          return;
      }
      setOcrError(null);
      setOcrResult(null);
      setIsOcrLoading(true);
