    Văn bản 1:
    ${text1}

    Văn bản 2:
    ${text2}`,
    config: { 
      tools: [{googleSearch: {}}],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: { type: Type.STRING, description: "Tóm tắt ngắn gọn điểm khác biệt chính" },
          similarityScore: { type: Type.NUMBER, description: "Phần trăm tương đồng 0-100" },
          differences: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                clause: { type: Type.STRING, description: "Tên điều khoản hoặc số thứ tự" },
                changeType: { type: Type.STRING, description: "Chọn: added, removed, modified, unchanged" },
                text1: { type: Type.STRING, description: "Nội dung ở VB1" },
                text2: { type: Type.STRING, description: "Nội dung ở VB2" },
