export default SettingsPanel;

import React, { useState, useCallback, useEffect } from 'react';
import { checkVietnameseSpelling, getContractDetails, evaluateContractLegality, compareDocuments } from './services/geminiService.ts';
import { CONTRACT_TYPES } from './constants.ts';
import type { SpellCheckResult, ContractDetails, LegalEvaluationResult, ComparisonResult } from './types.ts';
import { translations } from './translations.ts';
import FileUpload from './components/FileUpload.tsx';
import FileDropzone from './components/FileDropzone.tsx';
import ResultsDisplay from './components/ResultsDisplay.tsx';
import Loader from './components/Loader.tsx';
import ContractTypeSelector from './components/ContractTypeSelector.tsx';
import ContractDetailsModal from './components/ContractDetailsModal.tsx';
import LegalEvaluationDisplay from './components/LegalEvaluationDisplay.tsx';
import ComparisonDisplay from './components/ComparisonDisplay.tsx';
import SettingsPanel from './components/SettingsPanel.tsx';

type ActiveTab = 'analyze' | 'compare' | 'ocr';

const App: React.FC = () => {
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [lang, setLang] = useState<'vi' | 'en'>('vi');
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<ActiveTab>('analyze');
  const [file, setFile] = useState<File | null>(null);

  // State cho So sánh
  const [compareFile1, setCompareFile1] = useState<File | null>(null);
  const [compareFile2, setCompareFile2] = useState<File | null>(null);
  const [isComparing, setIsComparing] = useState<boolean>(false);
  const [comparisonResult, setComparisonResult] = useState<ComparisonResult | null>(null);

  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isEvaluating, setIsEvaluating] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedContractId, setSelectedContractId] = useState<string>(CONTRACT_TYPES[0].id);
  const [spellCheckResult, setSpellCheckResult] = useState<SpellCheckResult | null>(null);
  const [legalResult, setLegalResult] = useState<LegalEvaluationResult | null>(null);
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [modalContent, setModalContent] = useState<ContractDetails | null>(null);
  const [isModalLoading, setIsModalLoading] = useState<boolean>(false);
  const [modalError, setModalError] = useState<string | null>(null);

  const handleError = (err: any, setter: (msg: string) => void) => {
    const msg = err instanceof Error ? err.message : String(err);
    if (msg.toLowerCase().includes("api_key")) {
      setter(lang === 'vi' ? "Lỗi: Không tìm thấy API Key hoặc Key không hợp lệ." : "Error: API Key not found or invalid.");
    } else {
      setter(`${lang === 'vi' ? 'Lỗi hệ thống' : 'System error'}: ${msg}`);
    }
  };

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
    setSpellCheckResult(null);
    setLegalResult(null);
    setError(null);
  };

  const handleCheckSpelling = useCallback(async () => {
    if (!file) { setError(t.errorNoFile); return; }
    setIsLoading(true); setError(null);
    try {
      const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
      const result = await checkVietnameseSpelling(file, selectedContract?.name || 'Chung', lang);
      setSpellCheckResult(result);
    } catch (err) { handleError(err, setError); } finally { setIsLoading(false); }
  }, [file, selectedContractId, lang]);

  const handleEvaluateLegality = useCallback(async () => {
    if (!file) { setError(t.errorNoFile); return; }
    setIsEvaluating(true); setError(null);
    try {
        const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
        const result = await evaluateContractLegality(file, selectedContract?.name || 'Chung', lang);
        setLegalResult(result);
    } catch (err) { handleError(err, setError); } finally { setIsEvaluating(false); }
  }, [file, selectedContractId, lang]);

  const handleStartComparison = useCallback(async () => {
    if (!compareFile1 || !compareFile2) { setError(t.errorNoFiles); return; }
    setIsComparing(true); setError(null); setComparisonResult(null);
    try {
      const result = await compareDocuments(compareFile1, compareFile2, lang);
      setComparisonResult(result);
    } catch (err) { handleError(err, setError); } finally { setIsComparing(false); }
  }, [compareFile1, compareFile2, lang]);

  const handleViewDetails = useCallback(async () => {
    const selectedContract = CONTRACT_TYPES.find(c => c.id === selectedContractId);
    if (!selectedContract || selectedContract.id === 'general') return;
    setIsModalOpen(true); setIsModalLoading(true); setModalError(null);
    try {
      const details = await getContractDetails(selectedContract.name, lang);
      setModalContent(details);
    } catch (err) { handleError(err, setModalError); } finally { setIsModalLoading(false); }
  }, [selectedContractId, lang]);

  return (
    <div className={`min-h-screen transition-colors duration-500 flex flex-col p-4 sm:p-8 ${
      theme === 'dark' ? 'bg-slate-900 text-slate-100' : 'bg-slate-50 text-slate-900'
    }`}>
      <SettingsPanel theme={theme} setTheme={setTheme} lang={lang} setLang={setLang} />

      <div className="max-w-5xl mx-auto w-full pt-12 sm:pt-0">
        <header className="text-center mb-10">
          <div className={`inline-block px-3 py-1 mb-4 text-xs font-bold tracking-widest uppercase rounded-full border transition-all ${
            theme === 'dark' ? 'text-sky-400 bg-sky-900/30 border-sky-800' : 'text-indigo-600 bg-indigo-50 border-indigo-200'
          }`}>
            {t.tagline}
          </div>
          <h1 className={`text-5xl font-black mb-3 transition-colors ${theme === 'dark' ? 'text-white' : 'text-slate-900'}`}>
            {t.appTitle}
          </h1>
          <p className={`${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'} max-w-lg mx-auto font-medium`}>
            {t.appSubtitle}
          </p>
        </header>

        <div className={`rounded-3xl border shadow-2xl overflow-hidden mb-8 ring-1 transition-all ${
          theme === 'dark' ? 'bg-slate-800 border-slate-700 ring-white/5' : 'bg-white border-slate-200 ring-black/5'
        }`}>
          <div className={`flex p-1 border-b transition-colors ${theme === 'dark' ? 'bg-slate-900/50 border-slate-700' : 'bg-slate-100 border-slate-200'}`}>
            <button onClick={() => {setActiveTab('analyze'); setError(null);}} className={`flex-1 py-4 rounded-2xl font-bold transition-all ${
              activeTab === 'analyze' 
                ? (theme === 'dark' ? 'text-sky-400 bg-slate-800 shadow-lg' : 'text-indigo-600 bg-white shadow-md') 
                : (theme === 'dark' ? 'text-slate-500 hover:text-slate-300' : 'text-slate-400 hover:text-slate-600')
            }`}>
              {t.tabAnalyze}
            </button>
            <button onClick={() => {setActiveTab('compare'); setError(null);}} className={`flex-1 py-4 rounded-2xl font-bold transition-all ${
              activeTab === 'compare' 
                ? (theme === 'dark' ? 'text-sky-400 bg-slate-800 shadow-lg' : 'text-indigo-600 bg-white shadow-md') 
                : (theme === 'dark' ? 'text-slate-500 hover:text-slate-300' : 'text-slate-400 hover:text-slate-600')
            }`}>
              {t.tabCompare}
            </button>
            <button onClick={() => {setActiveTab('ocr'); setError(null);}} className={`flex-1 py-4 rounded-2xl font-bold transition-all ${
              activeTab === 'ocr' 
                ? (theme === 'dark' ? 'text-sky-400 bg-slate-800 shadow-lg' : 'text-indigo-600 bg-white shadow-md') 
                : (theme === 'dark' ? 'text-slate-500 hover:text-slate-300' : 'text-slate-400 hover:text-slate-600')
            }`}>
              {t.tabOcr}
            </button>
          </div>

          <div className="p-8">
            {activeTab === 'analyze' && (
              <>
                <ContractTypeSelector 
                  selectedType={selectedContractId} 
                  onTypeChange={setSelectedContractId} 
                  contractTypes={CONTRACT_TYPES} 
                  onViewDetails={handleViewDetails}
                  translations={t}
                  theme={theme}
                />
                <FileUpload 
                  file={file} 
                  onFileSelect={handleFileSelect} 
                  onCheck={handleCheckSpelling} 
                  onEvaluate={handleEvaluateLegality} 
                  isLoading={isLoading} 
                  isEvaluating={isEvaluating}
                  translations={t}
                  theme={theme}
                />
                {error && <div className={`mt-6 p-4 border rounded-xl text-center font-medium animate-pulse ${
                  theme === 'dark' ? 'bg-red-900/40 border-red-700 text-red-200' : 'bg-red-50 border-red-200 text-red-600'
                }`}>{error}</div>}
                {(isLoading || isEvaluating) && <Loader message={isLoading ? t.loadingSpelling : t.loadingLegality} theme={theme} />}
                {spellCheckResult && !isLoading && <ResultsDisplay result={spellCheckResult} translations={t} theme={theme} />}
                {legalResult && !isEvaluating && <LegalEvaluationDisplay result={legalResult} translations={t} theme={theme} />}
              </>
            )}

            {activeTab === 'compare' && (
              <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <FileDropzone title={t.file1Label} file={compareFile1} onFileSelect={setCompareFile1} theme={theme} translations={t} />
                  <FileDropzone title={t.file2Label} file={compareFile2} onFileSelect={setCompareFile2} theme={theme} translations={t} />
                </div>

                <div className="flex justify-center">
                  <button 
                    onClick={handleStartComparison}
                    disabled={!compareFile1 || !compareFile2 || isComparing}
                    className={`px-10 py-4 font-bold rounded-2xl shadow-xl transition-all flex items-center space-x-2 ${
                      isComparing 
                        ? 'bg-slate-700 text-slate-400' 
                        : (theme === 'dark' ? 'bg-sky-500 hover:bg-sky-600 text-white shadow-sky-500/20' : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-indigo-500/20')
                    }`}
                  >
                    {isComparing ? <><div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div><span>{t.comparingFiles}</span></> : t.btnCompare}
                  </button>
                </div>

                {error && <div className={`p-4 border rounded-xl text-center ${theme === 'dark' ? 'bg-red-900/40 border-red-700 text-red-200' : 'bg-red-50 border-red-200 text-red-600'}`}>{error}</div>}
                {isComparing && <Loader message={t.loadingComparing} theme={theme} />}
                {comparisonResult && !isComparing && <ComparisonDisplay result={comparisonResult} translations={t} theme={theme} />}
              </div>
            )}

            {activeTab === 'ocr' && (
               <div className={`text-center p-12 italic rounded-xl border border-dashed transition-all ${
                 theme === 'dark' ? 'text-slate-400 bg-slate-900/20 border-slate-700' : 'text-slate-500 bg-slate-50 border-slate-300'
               }`}>
                  {t.ocrInfo}
               </div>
            )}
          </div>
        </div>

        <footer className={`text-center text-xs py-10 transition-colors ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>
          <p className="mb-2">{t.footerDev} <span className={theme === 'dark' ? 'text-sky-500 font-bold' : 'text-indigo-600 font-bold'}>DI-IT</span></p>
          <p className="opacity-60">{t.footerDisclaimer}</p>
        </footer>
      </div>

      <ContractDetailsModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={CONTRACT_TYPES.find(c => c.id === selectedContractId)?.name || ''} 
        content={modalContent} 
        isLoading={isModalLoading} 
        error={modalError} 
        theme={theme}
      />
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import type { SpellCheckResult, ContractDetails, LegalEvaluationResult, ComparisonResult, OcrResult } from '../types';
import { readFileContent } from '../utils/fileReader';

const createAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "undefined" || apiKey === "") {
    throw new Error("API_KEY chưa được cấu hình. Hãy kiểm tra lại Settings trong Vercel.");
  }
  return new GoogleGenAI({ apiKey });
};

const safeJsonParse = (text: string | undefined) => {
  if (!text) throw new Error("Không nhận được phản hồi từ AI.");
  let clean = text.trim();
  const jsonMatch = clean.match(/\{[\s\S]*\}/);
  if (jsonMatch) clean = jsonMatch[0];
  try {
    return JSON.parse(clean);
  } catch (e) {
    console.error("Lỗi parse JSON:", clean);
    throw new Error("Dữ liệu AI trả về không đúng định dạng. Vui lòng thử lại.");
  }
};

export const checkVietnameseSpelling = async (file: File, contractName: string, lang: 'vi' | 'en' = 'vi'): Promise<SpellCheckResult> => {
  const text = await readFileContent(file);
  const ai = createAiClient();
  const outputLang = lang === 'vi' ? 'Tiếng Việt' : 'English';

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Bạn là Trợ lý Pháp lý chuyên nghiệp. Hãy kiểm tra chính tả, hành văn và tính trang trọng cho văn bản: ${contractName}.
    Hãy phản hồi kết quả bằng ngôn ngữ: ${outputLang}.\n\nNội dung:\n${text}`,
    config: { 
      tools: [{googleSearch: {}}],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          hasErrors: { type: Type.BOOLEAN },
          errors: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                incorrectWord: { type: Type.STRING },
                correctedWord: { type: Type.STRING },
                context: { type: Type.STRING }
              }
            }
          },
          formatErrors: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                errorType: { type: Type.STRING },
                description: { type: Type.STRING },
                recommendation: { type: Type.STRING }
              }
            }
          }
        },
        required: ["hasErrors"]
      }
    }
  });
  return { ...safeJsonParse(response.text), sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks };
};

export const evaluateContractLegality = async (file: File, contractName: string, lang: 'vi' | 'en' = 'vi'): Promise<LegalEvaluationResult> => {
  const text = await readFileContent(file);
  const ai = createAiClient();
  const outputLang = lang === 'vi' ? 'Tiếng Việt' : 'English';

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Bạn là Luật sư cao cấp. Phân tích rủi ro pháp lý cho loại: ${contractName}. 
    Tập trung vào: Điều khoản mơ hồ, nội dung bất lợi, thiếu căn cứ pháp lý.
    Hãy phản hồi kết quả bằng ngôn ngữ: ${outputLang}.\n\nNội dung văn bản:\n${text}`,
    config: { 
      tools: [{googleSearch: {}}],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          legalScore: { type: Type.NUMBER },
          feedback: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                type: { type: Type.STRING },
                clause: { type: Type.STRING },
                comment: { type: Type.STRING },
                recommendation: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  });
  const result = safeJsonParse(response.text);
  return { legalScore: result.legalScore ?? 0, feedback: result.feedback || [], sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks };
};

export const compareDocuments = async (file1: File, file2: File, lang: 'vi' | 'en' = 'vi'): Promise<ComparisonResult> => {
  const text1 = await readFileContent(file1);
  const text2 = await readFileContent(file2);
  const ai = createAiClient();
  const outputLang = lang === 'vi' ? 'Tiếng Việt' : 'English';

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Bạn là Luật sư chuyên gia cấp cao. Hãy so sánh chi tiết 2 văn bản dưới đây để CHỌN BẢN AN TOÀN HƠN.
    Hãy phản hồi kết quả bằng ngôn ngữ: ${outputLang}.

    Yêu cầu:
    1. Chỉ ra điểm GIỐNG NHAU.
    2. Chỉ ra điểm KHÁC NHAU (Câu chữ, ý nghĩa pháp lý).
    3. Liệt kê nội dung bị THÊM / BỚT / CHỈNH SỬA theo từng điều khoản.
    4. Phân tích rủi ro: Điều khoản mơ hồ, bất lợi cho một bên.
    5. Kiểm tra tính trang trọng và chuẩn văn bản pháp lý.

    Văn bản 1 (Gốc/Tham chiếu):
    ${text1}

    Văn bản 2 (Sửa đổi/Đối ứng):
    ${text2}`,
    config: { 
      tools: [{googleSearch: {}}],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: { type: Type.STRING, description: "Tóm tắt ngắn gọn sự khác biệt và đánh giá tổng quan" },
          similarityScore: { type: Type.NUMBER, description: "Phần trăm tương đồng thực tế" },
          differences: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                clause: { type: Type.STRING },
                changeType: { type: Type.STRING, description: "added, removed, modified, unchanged" },
                text1: { type: Type.STRING },
                text2: { type: Type.STRING },
                legalImpact: { type: Type.STRING, description: "Rủi ro hoặc lợi ích pháp lý của thay đổi này" }
              }
            }
          },
          legalRemarks: { type: Type.STRING, description: "Nhận xét chi tiết về các lỗ hổng và rủi ro (Markdown)" },
          formalAssessment: { type: Type.STRING, description: "Đánh giá lỗi chính tả, hành văn và tính chuẩn mực (Markdown)" },
          recommendations: { type: Type.STRING, description: "Đề xuất cải thiện cụ thể (Markdown)" },
          bestVersion: { type: Type.STRING, description: "file1 hoặc file2 kèm lý do" }
        },
        required: ["summary", "similarityScore", "differences", "bestVersion"]
      }
    }
  });

  const result = safeJsonParse(response.text);
  return {
    ...result,
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks
  };
};

export const getContractDetails = async (contractName: string, lang: 'vi' | 'en' = 'vi'): Promise<ContractDetails> => {
  const ai = createAiClient();
  const outputLang = lang === 'vi' ? 'Tiếng Việt' : 'English';
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Cung cấp quy định pháp luật và điều khoản bắt buộc cho: ${contractName}. Hãy trình bày bằng: ${outputLang}.`,
    config: { tools: [{googleSearch: {}}] }
  });
  return { details: response.text || "Không có dữ liệu.", sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks };
};

import React, { useRef, useState, useCallback } from 'react';

interface FileUploadProps {
  file: File | null;
  onFileSelect: (file: File) => void;
  onCheck: () => void;
  onEvaluate: () => void;
  isLoading: boolean;
  isEvaluating: boolean;
  translations: any;
  theme: 'dark' | 'light';
}

const FileUpload: React.FC<FileUploadProps> = ({ file, onFileSelect, onCheck, onEvaluate, isLoading, isEvaluating, translations, theme }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const t = translations;

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files[0]) {
      onFileSelect(event.target.files[0]);
    }
  };

  const handleClick = () => {
    fileInputRef.current?.click();
  };

  const onDragEnter = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  }, []);

  const onDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  }, []);

  const onDragOver = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const onDrop = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const droppedFile = e.dataTransfer.files[0];
      const fileName = droppedFile.name.toLowerCase();
      if (fileName.endsWith('.docx') || fileName.endsWith('.pdf')) {
        onFileSelect(droppedFile);
      } else {
        alert("DOCX/PDF only.");
      }
      e.dataTransfer.clearData();
    }
  }, [onFileSelect]);

  return (
    <div className="flex flex-col items-center">
      <div
        onDragEnter={onDragEnter}
        onDragLeave={onDragLeave}
        onDragOver={onDragOver}
        onDrop={onDrop}
        onClick={handleClick}
        className={`w-full p-8 sm:p-10 text-center border-2 border-dashed rounded-xl cursor-pointer transition-all duration-300 ${
          isDragging 
            ? (theme === 'dark' ? 'border-sky-400 bg-sky-900/30' : 'border-indigo-400 bg-indigo-50') 
            : (theme === 'dark' ? 'border-slate-600 hover:border-sky-500 hover:bg-slate-700/50' : 'border-slate-300 hover:border-indigo-500 hover:bg-slate-50')
        }`}
      >
        <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept=".docx,.pdf" />
        <div className="flex flex-col items-center justify-center pointer-events-none">
          <svg className={`w-12 h-12 mb-3 ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`} aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 20 16">
            <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 13h3a3 3 0 0 0 0-6h-.025A5.56 5.56 0 0 0 16 6.5 5.5 5.5 0 0 0 5.207 5.021C5.137 5.017 5.071 5 5 5a4 4 0 0 0 0 8h2.167M10 15V6m0 0L8 8m2-2 2 2"/>
          </svg>
          <p className={`mb-2 text-sm ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>
            <span className={`font-semibold ${theme === 'dark' ? 'text-sky-400' : 'text-indigo-600'}`}>{t.uploadTitle}</span> {t.uploadDrag}
          </p>
          <p className={`text-xs ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>{t.uploadSupport}</p>
        </div>
      </div>
      {file && (
        <div className={`w-full text-center text-sm p-3 rounded-lg mt-6 transition-colors ${
          theme === 'dark' ? 'text-slate-300 bg-slate-700/50' : 'text-slate-600 bg-slate-100'
        }`}>
          <p><span className="font-medium">{t.selectedFile}:</span> {file.name}</p>
        </div>
      )}
      <div className="flex flex-col sm:flex-row items-center justify-center space-y-4 sm:space-y-0 sm:space-x-4 mt-6 w-full">
        <button
          onClick={onCheck}
          disabled={!file || isLoading || isEvaluating}
          className={`w-full sm:w-auto px-8 py-3 text-base font-semibold text-white rounded-lg shadow-md transition-all ${
            theme === 'dark' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-indigo-600 hover:bg-indigo-700'
          } disabled:bg-slate-400 disabled:cursor-not-allowed`}
        >
          {isLoading ? translations.loadingSpelling : t.btnSpelling}
