// This file contains the logic to read and extract text from various file types
// entirely on the client-side (in the browser).

declare const mammoth: any;
declare const pdfjsLib: any;
declare const Tesseract: any;

/**
 * Trích xuất các trang của PDF thành mảng các Base64 Images để gửi cho AI
 */
export const extractPdfPagesAsImages = async (file: File): Promise<string[]> => {
    const pdfLib = (window as any).pdfjsLib || pdfjsLib;
    if (!pdfLib) throw new Error("PDF.js not loaded");

    pdfLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

    const arrayBuffer = await file.arrayBuffer();
    const loadingTask = pdfLib.getDocument({ data: new Uint8Array(arrayBuffer) });
    const pdfDoc = await loadingTask.promise;
    const images: string[] = [];

    // Giới hạn OCR 10 trang đầu để tránh quá tải (có thể tăng thêm tùy nhu cầu)
    const pageLimit = Math.min(pdfDoc.numPages, 10);

    for (let i = 1; i <= pageLimit; i++) {
        const page = await pdfDoc.getPage(i);
        const viewport = page.getViewport({ scale: 2.0 }); // Scale 2.0 cho độ nét cao
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        canvas.height = viewport.height;
        canvas.width = viewport.width;

        await page.render({ canvasContext: context!, viewport }).promise;
        const imageData = canvas.toDataURL('image/jpeg', 0.85); // Dùng JPEG để tối ưu dung lượng gửi AI
        images.push(imageData.split(',')[1]); // Lấy phần data base64 thô
    }

    return images;
};

export const readFileContent = async (file: File): Promise<string> => {
    const fileExt = file.name.split('.').pop()?.toLowerCase();

    if (fileExt === 'docx') {
        if (typeof mammoth === 'undefined') throw new Error("Mammoth not loaded");
        const arrayBuffer = await file.arrayBuffer();
        const result = await mammoth.extractRawText({ arrayBuffer });
        return result.value;
    } 

    if (fileExt === 'pdf') {
        const pdfLib = (window as any).pdfjsLib || pdfjsLib;
        if (!pdfLib) throw new Error("PDF.js not loaded");

        pdfLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

        const arrayBuffer = await file.arrayBuffer();
        try {
            const loadingTask = pdfLib.getDocument({ data: new Uint8Array(arrayBuffer) });
            const pdfDoc = await loadingTask.promise;
            let fullText = '';

            for (let i = 1; i <= pdfDoc.numPages; i++) {
                const page = await pdfDoc.getPage(i);
                const textContent = await page.getTextContent();
                const pageText = textContent.items.map((item: any) => item.str).join(' ');

                if (pageText.trim().length < 10) {
                    const viewport = page.getViewport({ scale: 2.0 });
                    const canvas = document.createElement('canvas');
                    const context = canvas.getContext('2d');
                    canvas.height = viewport.height;
                    canvas.width = viewport.width;
                    await page.render({ canvasContext: context!, viewport }).promise;
                    const ocrText = await performOCR(canvas.toDataURL('image/png'));
                    fullText += ocrText + '\n';
                } else {
                    fullText += pageText + '\n';
                }
            }
            return fullText.trim();
        } catch (err) {
            throw new Error("Không thể đọc tệp PDF.");
        }
    } 

    if (['png', 'jpg', 'jpeg', 'bmp', 'webp'].includes(fileExt || '')) {
        const base64 = await fileToBase64(file);
        return await performOCR(base64);
    }

    throw new Error(`Định dạng tệp .${fileExt} không được hỗ trợ.`);
};

const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = error => reject(error);
    });
};

const performOCR = async (imageSource: any): Promise<string> => {
    if (typeof Tesseract === 'undefined') throw new Error("OCR not loaded");
    const { data: { text } } = await Tesseract.recognize(imageSource, 'vie');
    return text;
};

import { GoogleGenAI, Type } from "@google/genai";
import type { SpellCheckResult, ContractDetails, LegalEvaluationResult, ComparisonResult, OcrResult } from '../types';
import { readFileContent, extractPdfPagesAsImages } from '../utils/fileReader';

const createAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "undefined" || apiKey === "") {
    throw new Error("API_KEY chưa được cấu hình.");
  }
  return new GoogleGenAI({ apiKey });
};

const safeJsonParse = (text: string | undefined) => {
  if (!text) throw new Error("Không nhận được phản hồi từ AI.");
  let clean = text.trim();
  const jsonMatch = clean.match(/\{[\s\S]*\}/);
  if (jsonMatch) clean = jsonMatch[0];
  try {
    return JSON.parse(clean);
  } catch (e) {
    throw new Error("Dữ liệu AI trả về không đúng định dạng.");
  }
};

/**
 * OCR Chuyên sâu Ver 1.2 - Prompt 4 Giai đoạn
 */
export const performAdvancedOcr = async (file: File, lang: 'vi' | 'en' = 'vi'): Promise<OcrResult> => {
  const ai = createAiClient();
  const fileExt = file.name.split('.').pop()?.toLowerCase();
  const outputLang = lang === 'vi' ? 'Tiếng Việt' : 'English';

  let parts: any[] = [];

  // Giai đoạn chuẩn bị dữ liệu hình ảnh
  if (fileExt === 'pdf') {
      const pageImages = await extractPdfPagesAsImages(file);
      parts = pageImages.map(base64 => ({
          inlineData: { data: base64, mimeType: 'image/jpeg' }
      }));
  } else {
      const reader = new FileReader();
      const base64 = await new Promise<string>((resolve) => {
          reader.readAsDataURL(file);
          reader.onload = () => resolve((reader.result as string).split(',')[1]);
      });
      parts = [{ inlineData: { data: base64, mimeType: `image/${fileExt === 'jpg' ? 'jpeg' : fileExt}` } }];
  }

  // Thêm Prompt yêu cầu hệ thống
  const promptText = `Bạn là Trợ lý OCR & Phân tích Ngôn ngữ Tiếng Việt chuyên sâu. Nhiệm vụ của bạn là trích xuất và phân tích văn bản từ hình ảnh đính kèm.

=== QUY TRÌNH THỰC HIỆN ===
1. OCR & TRÍCH XUẤT: Giữ nguyên cấu trúc gốc (Tiêu đề, Mục, Điều, Khoản). Nhận diện đúng dấu tiếng Việt và ký tự số.
2. HIỆU CHỈNH AI: Tự động sửa lỗi OCR (nhầm I/l/1, O/0, d/đ). Chuẩn hóa từ ngữ trang trọng. Tuyệt đối không tự ý thêm nội dung ngoài bản gốc.
3. PHÂN TÍCH: Đánh giá độ chính xác, phát hiện câu văn mơ hồ hoặc thiếu chủ vị.
4. XUẤT KẾT QUẢ: Phải trả về định dạng JSON theo schema yêu cầu.

Hãy phản hồi bằng ngôn ngữ: ${outputLang}.`;

  parts.push({ text: promptText });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts },
    config: { 
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          cleanText: { type: Type.STRING, description: "Phần A: Nội dung văn bản sạch" },
          fixedErrors: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Phần B: Các lỗi OCR đã sửa" },
          checkRequired: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Phần C: Các đoạn cần kiểm tra lại" },
          qualityReport: { type: Type.STRING, description: "Phần D: Nhận xét tổng thể" },
          confidenceLevel: { type: Type.STRING, enum: ["High", "Medium", "Low"] }
        },
        required: ["cleanText", "fixedErrors", "checkRequired", "qualityReport", "confidenceLevel"]
      }
    }
  });

  return safeJsonParse(response.text);
};

