// Fix: Always use new GoogleGenAI({ apiKey: process.env.API_KEY }) directly as per guidelines.
const createAiClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const safeJsonParse = (text: string | undefined) => {
  if (!text) throw new Error("Không nhận được phản hồi từ AI.");
  let clean = text.trim();
  const jsonMatch = clean.match(/\{[\s\S]*\}/);
  if (jsonMatch) clean = jsonMatch[0];
  try {
    return JSON.parse(clean);
  } catch (e) {
    throw new Error("Dữ liệu AI trả về không đúng định dạng.");
  }
};

/**
 * OCR Chuyên sâu Ver 1.2 - Prompt 4 Giai đoạn
 */
export const performAdvancedOcr = async (file: File, lang: 'vi' | 'en' = 'vi'): Promise<OcrResult> => {
  const ai = createAiClient();
  const fileExt = file.name.split('.').pop()?.toLowerCase();
  const outputLang = lang === 'vi' ? 'Tiếng Việt' : 'English';

  let parts: any[] = [];

  // Giai đoạn chuẩn bị dữ liệu hình ảnh
  if (fileExt === 'pdf') {
      const pageImages = await extractPdfPagesAsImages(file);
      parts = pageImages.map(base64 => ({
          inlineData: { data: base64, mimeType: 'image/jpeg' }
      }));
  } else {
      const reader = new FileReader();
      const base64 = await new Promise<string>((resolve) => {
          reader.readAsDataURL(file);
          reader.onload = () => resolve((reader.result as string).split(',')[1]);
      });
      parts = [{ inlineData: { data: base64, mimeType: `image/${fileExt === 'jpg' ? 'jpeg' : fileExt}` } }];
  }

  // Thêm Prompt yêu cầu hệ thống
  const promptText = `Bạn là Trợ lý OCR & Phân tích Ngôn ngữ Tiếng Việt chuyên sâu. Nhiệm vụ của bạn là trích xuất và phân tích văn bản từ hình ảnh đính kèm.

=== QUY TRÌNH THỰC HIỆN ===
1. OCR & TRÍCH XUẤT: Giữ nguyên cấu trúc gốc (Tiêu đề, Mục, Điều, Khoản). Nhận diện đúng dấu tiếng Việt và ký tự số.
2. HIỆU CHỈNH AI: Tự động sửa lỗi OCR (nhầm I/l/1, O/0, d/đ). Chuẩn hóa từ ngữ trang trọng. Tuyệt đối không tự ý thêm nội dung ngoài bản gốc.
3. PHÂN TÍCH: Đánh giá độ chính xác, phát hiện câu văn mơ hồ hoặc thiếu chủ vị.
4. XUẤT KẾT QUẢ: Phải trả về định dạng JSON theo schema yêu cầu.

Hãy phản hồi bằng ngôn ngữ: ${outputLang}.`;

  parts.push({ text: promptText });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts },
    config: { 
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          cleanText: { type: Type.STRING, description: "Phần A: Nội dung văn bản sạch" },
          fixedErrors: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Phần B: Các lỗi OCR đã sửa" },
          checkRequired: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Phần C: Các đoạn cần kiểm tra lại" },
          qualityReport: { type: Type.STRING, description: "Phần D: Nhận xét tổng thể" },
          confidenceLevel: { type: Type.STRING, enum: ["High", "Medium", "Low"] }
        },
        required: ["cleanText", "fixedErrors", "checkRequired", "qualityReport", "confidenceLevel"]
      }
    }
  });

  return safeJsonParse(response.text);
};

