    switch (diff.changeType) {
      case 'added': return { label: 'THÊM MỚI', color: 'text-green-400', bg: 'bg-green-900/10' };
      case 'removed': return { label: 'LƯỢC BỎ', color: 'text-red-400', bg: 'bg-red-900/10' };
