import React, { useState, useCallback, useRef } from 'react';

interface FileDropzoneProps {
  file: File | null;
  onFileSelect: (file: File | null) => void;
  onFilesSelect?: (files: File[]) => void;
  title: React.ReactNode;
  theme: 'dark' | 'light';
  translations: any;
  acceptedFormats?: 'documents' | 'images' | 'ocr';
  multiple?: boolean;
}

const FileDropzone: React.FC<FileDropzoneProps> = ({ 
  file, 
  onFileSelect, 
  onFilesSelect,
  title, 
  theme, 
  translations, 
  acceptedFormats = 'documents',
  multiple = false
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = translations;

  let accept: string;
  let description: string;
  let acceptedMimeTypes: string[];
  let acceptedExtensions: string[];
  let alertMessage: string;

  if (acceptedFormats === 'images') {
      accept = "image/png,image/jpeg,image/gif,image/bmp,.png,.jpg,.jpeg,.gif,.bmp";
      description = "Hỗ trợ tệp ảnh (.png, .jpg, .bmp)";
      acceptedMimeTypes = ["image/png", "image/jpeg", "image/gif", "image/bmp"];
      acceptedExtensions = ['.png', '.jpg', '.jpeg', '.gif', '.bmp'];
      alertMessage = "Chỉ chấp nhận tệp ảnh (.png, .jpg, .gif, .bmp).";
  } else if (acceptedFormats === 'ocr') {
      accept = "image/png,image/jpeg,image/bmp,application/pdf,.png,.jpg,.jpeg,.bmp,.pdf";
      description = t.uploadSupport || "Hỗ trợ tệp ảnh (.png, .jpg) và .pdf";
      acceptedMimeTypes = ["image/png", "image/jpeg", "image/bmp", "application/pdf"];
      acceptedExtensions = ['.png', '.jpg', '.jpeg', '.bmp', '.pdf'];
      alertMessage = "Chỉ chấp nhận tệp ảnh hoặc tệp .pdf.";
  } else { // documents
      accept = "application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/pdf,.docx,.pdf";
      description = t.uploadSupport || "Hỗ trợ .docx, .pdf";
      acceptedMimeTypes = ["application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/pdf"];
      acceptedExtensions = ['.docx', '.pdf'];
      alertMessage = "Chỉ chấp nhận tệp .docx hoặc .pdf.";
  }

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files.length > 0) {
      if (multiple && onFilesSelect) {
        onFilesSelect(Array.from(event.target.files));
      } else {
        onFileSelect(event.target.files[0]);
      }
    }
  };

  const handleClick = () => {
    fileInputRef.current?.click();
  };

  const onDragEnter = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  }, []);

  const onDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  }, []);

  const onDragOver = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const onDrop = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const droppedFiles = Array.from(e.dataTransfer.files);
      const validFiles = droppedFiles.filter(f => {
        const fileName = f.name.toLowerCase();
        return acceptedMimeTypes.includes(f.type) || acceptedExtensions.some(ext => fileName.endsWith(ext));
      });

      if (validFiles.length > 0) {
        if (multiple && onFilesSelect) {
          onFilesSelect(validFiles);
        } else {
          onFileSelect(validFiles[0]);
        }
      } else {
        alert(alertMessage);
      }
      e.dataTransfer.clearData();
    }
  }, [onFileSelect, onFilesSelect, multiple, acceptedMimeTypes, acceptedExtensions, alertMessage]);

  const handleRemoveFile = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onFileSelect(null);
    if (fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  }

  return (
    <div className="flex flex-col w-full">
      <div className="mb-2 text-center">
        {typeof title === 'string' ? (
          <h3 className={`font-semibold ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{title}</h3>
        ) : (
          title
        )}
      </div>
      <div
        onClick={handleClick}
        onDragEnter={onDragEnter}
        onDragLeave={onDragLeave}
        onDragOver={onDragOver}
        onDrop={onDrop}
        className={`relative w-full p-6 text-center border-2 border-dashed rounded-xl cursor-pointer transition-all duration-300 ${
          isDragging 
            ? (theme === 'dark' ? 'border-sky-400 bg-sky-900/30' : 'border-indigo-400 bg-indigo-50') 
            : (theme === 'dark' ? 'border-slate-600 hover:border-sky-500 hover:bg-slate-700/50' : 'border-slate-300 hover:border-indigo-500 hover:bg-slate-50')
        }`}
      >
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileChange}
          className="hidden"
          accept={accept}
          multiple={multiple}
        />
        {!file ? (
            <div className="flex flex-col items-center justify-center pointer-events-none text-sm">
                <svg className={`w-10 h-10 mb-2 ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`} aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 20 16">
                  <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 13h3a3 3 0 0 0 0-6h-.025A5.56 5.56 0 0 0 16 6.5 5.5 5.5 0 0 0 5.207 5.021C5.137 5.017 5.071 5 5 5a4 4 0 0 0 0 8h2.167M10 15V6m0 0L8 8m2-2 2 2"/>
                </svg>
                <p className={`${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>
                    <span className={`font-semibold ${theme === 'dark' ? 'text-sky-400' : 'text-indigo-600'}`}>{t.uploadTitle}</span> {t.uploadDrag.split(' ').slice(1).join(' ')}
                </p>
                 <p className={`text-xs mt-1 ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>{description}</p>
            </div>
        ) : (
            <div className={`text-center text-sm ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>
                <p className="font-medium break-all">{file.name}</p>
                 <button 
                    onClick={handleRemoveFile} 
                    className={`mt-2 text-xs hover:underline ${theme === 'dark' ? 'text-red-400 hover:text-red-300' : 'text-red-600 hover:text-red-500'}`}
                    aria-label={`Xóa tệp ${file.name}`}
                 >
                    {t.removeFile || 'Xóa tệp'}
                </button>
            </div>
        )}
      </div>
    </div>
  );
};

export default FileDropzone;

import React, { useState, useCallback } from 'react';
import { checkVietnameseSpelling, getContractDetails, evaluateContractLegality, compareDocuments, performAdvancedOcr } from './services/geminiService.ts';
import { CONTRACT_TYPES } from './constants.ts';
import type { SpellCheckResult, ContractDetails, LegalEvaluationResult, ComparisonResult, OcrResult } from './types.ts';
import { translations } from './translations.ts';
import FileUpload from './components/FileUpload.tsx';
import FileDropzone from './components/FileDropzone.tsx';
import ResultsDisplay from './components/ResultsDisplay.tsx';
import Loader from './components/Loader.tsx';
import ContractTypeSelector from './components/ContractTypeSelector.tsx';
import ContractDetailsModal from './components/ContractDetailsModal.tsx';
import LegalEvaluationDisplay from './components/LegalEvaluationDisplay.tsx';
import ComparisonDisplay from './components/ComparisonDisplay.tsx';
import SettingsPanel from './components/SettingsPanel.tsx';
import OcrResultDisplay from './components/OcrResultDisplay.tsx';

type ActiveTab = 'analyze' | 'compare' | 'ocr';

const App: React.FC = () => {
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [lang, setLang] = useState<'vi' | 'en'>('vi');
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<ActiveTab>('analyze');
  const [file, setFile] = useState<File | null>(null);

  // State cho So sánh đa tài liệu
  const [compareFiles, setCompareFiles] = useState<File[]>([]);
  const [isComparing, setIsComparing] = useState<boolean>(false);
  const [comparisonResult, setComparisonResult] = useState<ComparisonResult | null>(null);

  // State cho OCR
  const [ocrFile, setOcrFile] = useState<File | null>(null);
  const [isOcrLoading, setIsOcrLoading] = useState<boolean>(false);
  const [ocrResult, setOcrResult] = useState<OcrResult | null>(null);

  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isEvaluating, setIsEvaluating] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedContractId, setSelectedContractId] = useState<string>(CONTRACT_TYPES[0].id);
  const [spellCheckResult, setSpellCheckResult] = useState<SpellCheckResult | null>(null);
  const [legalResult, setLegalResult] = useState<LegalEvaluationResult | null>(null);
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [modalContent, setModalContent] = useState<ContractDetails | null>(null);
  const [isModalLoading, setIsModalLoading] = useState<boolean>(false);
  const [modalError, setModalError] = useState<string | null>(null);

  const handleError = (err: any, setter: (msg: string) => void) => {
    const msg = err instanceof Error ? err.message : String(err);
    setter(`Lỗi: ${msg}`);
  };

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
    setSpellCheckResult(null);
    setLegalResult(null);
    setError(null);
  };

  const addCompareFiles = (newFiles: File[]) => {
    if (newFiles.length > 0) {
      setCompareFiles(prev => [...prev, ...newFiles]);
      setComparisonResult(null);
    }
  };

  const removeCompareFile = (index: number) => {
    setCompareFiles(prev => prev.filter((_, i) => i !== index));
    setComparisonResult(null);
  };

  const handleStartComparison = useCallback(async () => {
    if (compareFiles.length < 2) { 
      setError(lang === 'vi' ? "Vui lòng chọn ít nhất 2 tệp để so sánh." : "Please select at least 2 files."); 
      return; 
    }
    setIsComparing(true); setError(null); setComparisonResult(null);
    try {
      const result = await compareDocuments(compareFiles, lang);
      setComparisonResult(result);
    } catch (err) { handleError(err, setError); } finally { setIsComparing(false); }
  }, [compareFiles, lang]);

  const handleStartOcr = useCallback(async () => {
    if (!ocrFile) { setError(t.errorNoFile); return; }
    setIsOcrLoading(true); setError(null); setOcrResult(null);
    try {
      const result = await performAdvancedOcr(ocrFile, lang);
      setOcrResult(result);
    } catch (err) { handleError(err, setError); } finally { setIsOcrLoading(false); }
  }, [ocrFile, lang, t.errorNoFile]);

  const handleCheckSpelling = async () => {
    if (!file) return;
    setIsLoading(true); setError(null); setSpellCheckResult(null);
    try {
      const res = await checkVietnameseSpelling(file, selectedContractId, lang);
      setSpellCheckResult(res);
    } catch (err) { handleError(err, setError); } finally { setIsLoading(false); }
  };

  const handleEvaluateLegality = async () => {
    if (!file) return;
    setIsEvaluating(true); setError(null); setLegalResult(null);
    try {
      const res = await evaluateContractLegality(file, selectedContractId, lang);
      setLegalResult(res);
    } catch (err) { handleError(err, setError); } finally { setIsEvaluating(false); }
  };

  const handleViewDetails = async () => {
    const type = CONTRACT_TYPES.find(t => t.id === selectedContractId);
    if (!type || type.id === 'general') return;
    setIsModalOpen(true); setModalLoading(true); setModalContent(null); setModalError(null);
    try {
      const details = await getContractDetails(type.name, lang);
      setModalContent(details);
    } catch (err) { handleError(err, setModalError); } finally { setModalLoading(false); }
  };

  const setModalLoading = (val: boolean) => setIsModalLoading(val);

  return (
    <div className={`min-h-screen transition-colors duration-500 flex flex-col p-4 sm:p-8 ${
      theme === 'dark' ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'
    }`}>
      <SettingsPanel theme={theme} setTheme={setTheme} lang={lang} setLang={setLang} />

      <div className="max-w-5xl mx-auto w-full pt-12">
        <header className="text-center mb-12">
          <div className="inline-block px-4 py-1.5 mb-6 text-[10px] font-black tracking-[0.2em] uppercase rounded-full border border-sky-500/30 text-sky-400 bg-sky-900/20">
            Legal Assistant AI Professional
          </div>
          <h1 className="text-6xl font-black mb-4 tracking-tighter bg-clip-text text-transparent bg-gradient-to-r from-white via-sky-400 to-indigo-400">
            {t.appTitle}
          </h1>
          <p className="text-slate-400 max-w-2xl mx-auto text-lg font-medium">
            Phân tích văn bản pháp lý chuyên sâu bằng sức mạnh trí tuệ nhân tạo.
          </p>
        </header>

        <nav className={`flex p-1 rounded-3xl mb-10 border transition-all ${theme === 'dark' ? 'bg-slate-900/80 border-slate-800' : 'bg-white border-slate-200 shadow-lg'}`}>
          {(['analyze', 'compare', 'ocr'] as ActiveTab[]).map(tab => (
            <button 
              key={tab} 
              onClick={() => {setActiveTab(tab); setError(null);}} 
              className={`flex-1 py-4 px-6 rounded-2xl font-bold uppercase text-xs tracking-widest transition-all ${
                activeTab === tab 
                  ? (theme === 'dark' ? 'text-white bg-sky-600 shadow-xl shadow-sky-900/40' : 'text-white bg-indigo-600 shadow-lg') 
                  : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              {tab === 'analyze' ? t.tabAnalyze : tab === 'compare' ? t.tabCompare : t.tabOcr}
            </button>
          ))}
        </nav>

        <main className={`rounded-[2.5rem] border shadow-2xl p-8 sm:p-12 mb-12 transition-all ${
          theme === 'dark' ? 'bg-slate-900/50 border-slate-800' : 'bg-white border-slate-100 shadow-indigo-100'
        }`}>
          {error && (
            <div className="mb-6 p-4 rounded-xl bg-red-900/20 border border-red-700/50 text-red-400 text-sm font-bold text-center">
              {error}
            </div>
          )}

          {activeTab === 'analyze' && (
            <div className="space-y-8">
              <ContractTypeSelector 
                selectedType={selectedContractId} 
                onTypeChange={setSelectedContractId} 
                contractTypes={CONTRACT_TYPES} 
                onViewDetails={handleViewDetails}
                translations={t}
                theme={theme}
              />
              <FileUpload file={file} onFileSelect={handleFileSelect} onCheck={handleCheckSpelling} onEvaluate={handleEvaluateLegality} isLoading={isLoading} isEvaluating={isEvaluating} translations={t} theme={theme} />
              {spellCheckResult && <ResultsDisplay result={spellCheckResult} translations={t} theme={theme} />}
              {legalResult && <LegalEvaluationDisplay result={legalResult} translations={t} theme={theme} />}
            </div>
          )}

          {activeTab === 'compare' && (
            <div className="space-y-10">
              <div className="grid grid-cols-1 gap-6">
                <FileDropzone 
                  title={<h3 className="font-bold text-red-500">( Bạn hãy upload một lần 2 file liên tục để so sánh )</h3>} 
                  file={null} 
                  onFileSelect={() => {}} 
                  onFilesSelect={addCompareFiles}
                  theme={theme} 
                  translations={t} 
                  multiple={true}
                />
              </div>

              {compareFiles.length > 0 && (
                <div className="space-y-3">
                  <h4 className="text-sm font-bold uppercase text-slate-500 mb-4 tracking-widest">Danh sách tài liệu ({compareFiles.length})</h4>
                  {compareFiles.map((f, i) => (
                    <div key={i} className="flex items-center justify-between p-4 rounded-2xl bg-slate-800/50 border border-slate-700/50">
                      <div className="flex items-center space-x-3">
                        <div className="w-8 h-8 rounded-lg bg-sky-500/10 flex items-center justify-center text-sky-400 font-black text-xs">{i+1}</div>
                        <span className="text-sm font-bold text-slate-200">{f.name}</span>
                      </div>
                      <button onClick={() => removeCompareFile(i)} className="text-red-400 hover:text-red-300 p-2">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                      </button>
                    </div>
                  ))}
                  <div className="text-center">
                    <button onClick={() => setCompareFiles([])} className="text-xs text-slate-500 hover:text-slate-300 underline font-bold uppercase tracking-widest">
                      Xóa tất cả
                    </button>
                  </div>
                </div>
              )}

              <div className="flex justify-center pt-6">
                <button 
                  onClick={handleStartComparison}
                  disabled={compareFiles.length < 2 || isComparing}
                  className={`px-12 py-5 font-black uppercase text-xs tracking-[0.2em] rounded-2xl shadow-2xl transition-all ${
                    isComparing ? 'bg-slate-800 text-slate-500' : 'bg-sky-600 hover:bg-sky-500 text-white shadow-sky-900/40'
                  } disabled:opacity-50`}
                >
                  {isComparing ? 'Đang phân tích...' : t.btnCompare}
                </button>
              </div>

              {isComparing && <Loader message="AI đang đối chiếu từng chi tiết nhỏ nhất giữa các văn bản..." theme={theme} />}
              {comparisonResult && <ComparisonDisplay result={comparisonResult} translations={t} theme={theme} />}
            </div>
          )}

          {activeTab === 'ocr' && (
            <div className="space-y-10">
              <FileDropzone title="Tải ảnh hoặc PDF Scan" file={ocrFile} onFileSelect={setOcrFile} theme={theme} translations={t} acceptedFormats="ocr" />
              <div className="flex justify-center">
                <button onClick={handleStartOcr} disabled={!ocrFile || isOcrLoading} className="px-12 py-5 font-black uppercase text-xs tracking-[0.2em] rounded-2xl bg-sky-600 hover:bg-sky-500 text-white">
                   {isOcrLoading ? 'Đang trích xuất...' : t.btnStartOcr}
                </button>
              </div>
              {isOcrLoading && <Loader message={t.ocrProcessing} theme={theme} />}
              {ocrResult && <OcrResultDisplay result={ocrResult} translations={t} theme={theme} originalFileName={ocrFile?.name || 'ocr'} />}
            </div>
          )}
        </main>

        <footer className="text-center pb-12">
          <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.3em] mb-3">Develop by DI-IT Department</p>
          <p className="text-slate-600 text-[10px] uppercase opacity-50">{t.footerDisclaimer}</p>
        </footer>
      </div>

      <ContractDetailsModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={CONTRACT_TYPES.find(t => t.id === selectedContractId)?.name || ''} 
        content={modalContent} 
        isLoading={isModalLoading} 
        error={modalError} 
        theme={theme} 
      />
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef } from 'react';

interface FileDropzoneProps {
  file: File | null;
  onFileSelect: (file: File | null) => void;
  onFilesSelect?: (files: File[]) => void;
  title: React.ReactNode;
  theme: 'dark' | 'light';
  translations: any;
  acceptedFormats?: 'documents' | 'images' | 'ocr';
  multiple?: boolean;
}

const FileDropzone: React.FC<FileDropzoneProps> = ({ 
  file, 
  onFileSelect, 
  onFilesSelect,
  title, 
  theme, 
  translations, 
  acceptedFormats = 'documents',
  multiple = false
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = translations;

  let accept: string;
  let description: string;
  let acceptedMimeTypes: string[];
  let acceptedExtensions: string[];
  let alertMessage: string;

  if (acceptedFormats === 'images') {
      accept = "image/png,image/jpeg,image/gif,image/bmp,.png,.jpg,.jpeg,.gif,.bmp";
      description = "Hỗ trợ tệp ảnh (.png, .jpg, .bmp)";
      acceptedMimeTypes = ["image/png", "image/jpeg", "image/gif", "image/bmp"];
      acceptedExtensions = ['.png', '.jpg', '.jpeg', '.gif', '.bmp'];
      alertMessage = "Chỉ chấp nhận tệp ảnh (.png, .jpg, .gif, .bmp).";
  } else if (acceptedFormats === 'ocr') {
      accept = "image/png,image/jpeg,image/bmp,application/pdf,.png,.jpg,.jpeg,.bmp,.pdf";
      description = t.uploadSupport || "Hỗ trợ tệp ảnh (.png, .jpg) và .pdf";
      acceptedMimeTypes = ["image/png", "image/jpeg", "image/bmp", "application/pdf"];
      acceptedExtensions = ['.png', '.jpg', '.jpeg', '.bmp', '.pdf'];
      alertMessage = "Chỉ chấp nhận tệp ảnh hoặc tệp .pdf.";
  } else { // documents
      accept = "application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/pdf,.docx,.pdf";
      description = t.uploadSupport || "Hỗ trợ .docx, .pdf";
      acceptedMimeTypes = ["application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/pdf"];
      acceptedExtensions = ['.docx', '.pdf'];
      alertMessage = "Chỉ chấp nhận tệp .docx hoặc .pdf.";
  }

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files.length > 0) {
      if (multiple && onFilesSelect) {
        onFilesSelect(Array.from(event.target.files));
      } else {
        onFileSelect(event.target.files[0]);
      }
    }
  };

  const handleClick = () => {
    fileInputRef.current?.click();
  };

  const onDragEnter = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  }, []);

  const onDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  }, []);

  const onDragOver = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const onDrop = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      // FIX: Explicitly cast dropped files to File[] to avoid 'unknown' type issues when accessing name and type properties
      const droppedFiles = Array.from(e.dataTransfer.files) as File[];
      const validFiles = droppedFiles.filter(f => {
        const fileName = f.name.toLowerCase();
        return acceptedMimeTypes.includes(f.type) || acceptedExtensions.some(ext => fileName.endsWith(ext));
      });

      if (validFiles.length > 0) {
        if (multiple && onFilesSelect) {
          onFilesSelect(validFiles);
        } else {
          onFileSelect(validFiles[0]);
        }
      } else {
        alert(alertMessage);
      }
      e.dataTransfer.clearData();
    }
  }, [onFileSelect, onFilesSelect, multiple, acceptedMimeTypes, acceptedExtensions, alertMessage]);

  const handleRemoveFile = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onFileSelect(null);
    if (fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  }

  return (
    <div className="flex flex-col w-full">
      <div className="mb-2 text-center">
        {typeof title === 'string' ? (
          <h3 className={`font-semibold ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{title}</h3>
        ) : (
          title
        )}
      </div>
      <div
        onClick={handleClick}
        onDragEnter={onDragEnter}
        onDragLeave={onDragLeave}
        onDragOver={onDragOver}
        onDrop={onDrop}
        className={`relative w-full p-6 text-center border-2 border-dashed rounded-xl cursor-pointer transition-all duration-300 ${
          isDragging 
            ? (theme === 'dark' ? 'border-sky-400 bg-sky-900/30' : 'border-indigo-400 bg-indigo-50') 
            : (theme === 'dark' ? 'border-slate-600 hover:border-sky-500 hover:bg-slate-700/50' : 'border-slate-300 hover:border-indigo-500 hover:bg-slate-50')
        }`}
      >
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileChange}
          className="hidden"
          accept={accept}
          multiple={multiple}
        />
        {!file ? (
            <div className="flex flex-col items-center justify-center pointer-events-none text-sm">
                <svg className={`w-10 h-10 mb-2 ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`} aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 20 16">
                  <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 13h3a3 3 0 0 0 0-6h-.025A5.56 5.56 0 0 0 16 6.5 5.5 5.5 0 0 0 5.207 5.021C5.137 5.017 5.071 5 5 5a4 4 0 0 0 0 8h2.167M10 15V6m0 0L8 8m2-2 2 2"/>
                </svg>
                <p className={`${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>
                    <span className={`font-semibold ${theme === 'dark' ? 'text-sky-400' : 'text-indigo-600'}`}>{t.uploadTitle}</span> {t.uploadDrag.split(' ').slice(1).join(' ')}
                </p>
                 <p className={`text-xs mt-1 ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>{description}</p>
            </div>
        ) : (
            <div className={`text-center text-sm ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>
                <p className="font-medium break-all">{file.name}</p>
                 <button 
                    onClick={handleRemoveFile} 
