export const compareDocuments = async (files: File[], lang: 'vi' | 'en' = 'vi'): Promise<ComparisonResult> => {
  const ai = createAiClient();
  const outputLang = lang === 'vi' ? 'Tiếng Việt' : 'English';

  // Đọc nội dung tất cả các file
  const contents = await Promise.all(files.map(async (f, idx) => {
    const text = await readFileContent(f);
    return `--- TÀI LIỆU ${idx + 1}: ${f.name} ---\n${text}\n`;
  }));

  const allText = contents.join('\n\n');

  const prompt = `Bạn là Trợ lý Pháp lý AI chuyên về đối chiếu hợp đồng.
Hãy thực hiện SO SÁNH CHI TIẾT các tài liệu đã cung cấp.

=== YÊU CẦU ===
1. So sánh theo 4 cấp độ: Câu chữ, Nội dung, Điều khoản pháp lý, Mức độ rủi ro.
2. Xác định rõ: Giống nhau, khác nhau, thêm mới, lược bỏ, chỉnh sửa.

=== NGUYÊN TẮC BẮT BUỘC ===
- Trung thành tuyệt đối với tài liệu. Không suy đoán ngoài tài liệu.
- Phân tích rủi ro: Điều khoản mơ hồ, bất lợi, gây tranh chấp.

=== CẤU TRÚC PHẢN HỒI (JSON) ===
I. summary: Tóm tắt nhanh sự khác biệt chính.
II. detailedTable: Danh sách so sánh chi tiết.
III. legalRemarks: Nhận xét pháp lý sâu về rủi ro.
IV. recommendations: Đề xuất chỉnh sửa/lưu ý.

Ngôn ngữ phản hồi: ${outputLang}.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [
      { text: prompt },
      { text: allText }
    ],
    config: { 
      tools: [{googleSearch: {}}],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: { type: Type.STRING },
          detailedTable: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                clause: { type: Type.STRING },
                changeType: { type: Type.STRING, enum: ['added', 'removed', 'modified', 'unchanged'] },
                description: { type: Type.STRING },
                impact: { type: Type.STRING }
              }
            }
          },
          legalRemarks: { type: Type.STRING },
          recommendations: { type: Type.STRING }
        },
        required: ["summary", "detailedTable", "legalRemarks", "recommendations"]
      }
    }
  });

  return { ...safeJsonParse(response.text), sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks };
};

